extern "C" float sqrtf(float);
typedef float rational_t;
const rational_t SMALL_DIST = 0.00001f;
inline rational_t fast_recip_sqrt(rational_t x) { return 1.0F/(rational_t)sqrtf(x); }
class vector3d {
public:
  typedef rational_t T;
  T x,y,z;
  inline vector3d() {}
  inline vector3d(const vector3d& v) { x=v.x; y=v.y; z=v.z; }
  inline vector3d(T _x,T _y,T _z) { x=_x; y=_y; z=_z; }
  inline vector3d& operator=(const vector3d& v) { x=v.x; y=v.y; z=v.z; return *this; }
  inline vector3d& operator*=(T d) { x*=d; y*=d; z*=d; return *this; }
  inline T length2() const { return x*x+y*y+z*z; }
  inline vector3d& normalize() { T l2=length2(); if(l2>SMALL_DIST*SMALL_DIST) *this*=fast_recip_sqrt(l2); return *this; }
};
inline vector3d operator-(const vector3d&a,const vector3d&b){return vector3d(a.x-b.x,a.y-b.y,a.z-b.z);}
inline vector3d cross(const vector3d&a,const vector3d&b){vector3d v(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x);return v;}
class vector4d { public: float x,y,z,w; };
class matrix4x4 { public: vector4d x __attribute__((aligned(16))); vector4d y,z,w; };
class po {
  matrix4x4 m;
public:
  inline const vector3d& get_position() const { return *(const vector3d*)&m.w; }
  void set_facing(const vector3d& v) __asm__("set_facing__2poRC8vector3d");
};
void po::set_facing( const vector3d& v )
{
  vector3d zv = v - get_position();
  zv.normalize();
  if(( zv.y > 0.9999f )&&( zv.y < 1.0001f ))
  {
    m.x.x= 1.0f;  m.x.y= 0.0f;  m.x.z= 0.0f;
    m.y.x= 0.0f;  m.y.y= 0.0f;  m.y.z=-1.0f;
    m.z.x= 0.0f;  m.z.y= 1.0f;  m.z.z= 0.0f;
  }
  else if(( zv.y < -0.9999f )&&( zv.y > -1.0001f ))
  {
    m.x.x= 1.0f;  m.x.y= 0.0f;  m.x.z= 0.0f;
    m.y.x= 0.0f;  m.y.y= 0.0f;  m.y.z= 1.0f;
    m.z.x= 0.0f;  m.z.y= -1.0f;  m.z.z= 0.0f;
  }
  else
  {
    vector3d yv(0.0f,1.0f,0.0f);
    vector3d xv = cross( yv, zv );
    xv.normalize();
    yv = cross( zv, xv );
    yv.normalize();
    m.x.x=xv.x;  m.x.y=xv.y;  m.x.z=xv.z;
    m.y.x=yv.x;  m.y.y=yv.y;  m.y.z=yv.z;
    m.z.x=zv.x;  m.z.y=zv.y;  m.z.z=zv.z;
  }
}
